function validDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function createLotView(lot, viewer, leader, onOffer) {
  if (lot === null || typeof lot !== "object" ||
      !Number.isSafeInteger(lot.reserveCents) || lot.reserveCents < 0 ||
      typeof lot.ownerId !== "string" || lot.ownerId.length === 0 ||
      typeof lot.ownerName !== "string" || lot.ownerName.length === 0 ||
      typeof lot.eventDate !== "string" || !validDate(lot.eventDate) ||
      typeof lot.startTime !== "string" || !/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(lot.startTime) ||
      viewer === null || typeof viewer !== "object" ||
      typeof viewer.id !== "string" || viewer.id.length === 0 ||
      typeof onOffer !== "function") {
    throw new TypeError("invalid lot arguments");
  }
  if (leader !== null && (typeof leader !== "object" ||
      typeof leader.name !== "string" || leader.name.length === 0)) {
    throw new TypeError("invalid leader");
  }
  const canOffer = viewer.id === lot.ownerId;
  return {
    price: (lot.reserveCents / 100).toFixed(2),
    owner: lot.ownerName,
    schedule: lot.eventDate + " " + lot.startTime,
    leader: leader === null ? "No leader" : leader.name,
    canOffer,
    placeOffer: function placeOffer() {
      return canOffer ? onOffer() : false;
    }
  };
}

module.exports = { createLotView };

