"use strict";

const assert = require("node:assert/strict");
const api = require("./solution");
assert.deepStrictEqual(Object.keys(api), ["createLotView"]);
const { createLotView } = api;

const lot = {
  reserveCents: 12345,
  ownerId: "owner-1",
  ownerName: "Asha",
  eventDate: "2024-02-29",
  startTime: "09:05"
};
const viewer = { id: "viewer-1" };
const leader = { name: "Dev" };
let calls = 0;
const view = createLotView(lot, viewer, leader, () => {
  calls += 1;
  return "offered";
});
assert.deepStrictEqual(
  { price: view.price, owner: view.owner, schedule: view.schedule, leader: view.leader, canOffer: view.canOffer },
  { price: "123.45", owner: "Asha", schedule: "2024-02-29 09:05", leader: "Dev", canOffer: true }
);
assert.strictEqual(typeof view.placeOffer, "function");
assert.strictEqual(view.placeOffer(), "offered");
assert.strictEqual(calls, 1);

lot.reserveCents = 0;
lot.ownerName = "Changed";
lot.eventDate = "2000-01-01";
viewer.id = "owner-1";
leader.name = "Changed leader";
assert.deepStrictEqual(
  { price: view.price, owner: view.owner, schedule: view.schedule, leader: view.leader, canOffer: view.canOffer },
  { price: "123.45", owner: "Asha", schedule: "2024-02-29 09:05", leader: "Dev", canOffer: true }
);

let blockedCalls = 0;
const blocked = createLotView(
  { reserveCents: 0, ownerId: "same", ownerName: "Owner", eventDate: "2025-12-31", startTime: "23:59" },
  { id: "same" },
  null,
  () => { blockedCalls += 1; }
);
assert.strictEqual(blocked.price, "0.00");
assert.strictEqual(blocked.leader, "No leader");
assert.strictEqual(blocked.canOffer, false);
assert.strictEqual(blocked.placeOffer(), false);
assert.strictEqual(blockedCalls, 0);

const baseLot = { reserveCents: 1, ownerId: "o", ownerName: "Owner", eventDate: "2025-01-01", startTime: "00:00" };
const validViewer = { id: "v" };
const fn = () => {};
const invalidLots = [
  null,
  {},
  { ...baseLot, reserveCents: -1 },
  { ...baseLot, reserveCents: 1.5 },
  { ...baseLot, reserveCents: Number.MAX_SAFE_INTEGER + 1 },
  { ...baseLot, ownerId: "" },
  { ...baseLot, ownerName: "" },
  { ...baseLot, eventDate: "2023-02-29" },
  { ...baseLot, eventDate: "2024-02-30" },
  { ...baseLot, eventDate: "2025-1-01" },
  { ...baseLot, startTime: "24:00" },
  { ...baseLot, startTime: "9:05" },
  { ...baseLot, startTime: "12:60" }
];
for (const invalid of invalidLots) {
  assert.throws(() => createLotView(invalid, validViewer, null, fn), TypeError);
}
for (const invalidViewer of [null, {}, { id: "" }, { id: 1 }]) {
  assert.throws(() => createLotView(baseLot, invalidViewer, null, fn), TypeError);
}
for (const invalidLeader of [{}, { name: "" }, { name: 1 }, "leader"]) {
  assert.throws(() => createLotView(baseLot, validViewer, invalidLeader, fn), TypeError);
}
assert.throws(() => createLotView(baseLot, validViewer, null, null), TypeError);

